unsigned int ultrasonic_read(void)
{
    unsigned int ticks;
    ECHO=1; TRIG=0;
    if(ECHO!=0) return 0;
    TRIG=1; wait_ticks(20); TRIG=0;
    timer0_start();
    while(ECHO==0) {
        if(TF0!=0) { TR0=0; return 0; }
    }
    timer0_start();
    while(ECHO!=0) {
        if(TF0!=0) { TR0=0; return 0; }
    }
    TR0=0;
    if(TF0!=0) return 0;
    ticks=((unsigned int)TH0<<8)|TL0;
    return ticks;
}

void lcd_init(void)
{
    LCD_E=0; LCD_RS=0; LCD_RW=0;
    delay_ms(40);
    lcd_write(0x30,0); delay_ms(5);
    lcd_write(0x30,0); delay_ms(2);
    lcd_write(0x30,0);
    lcd_write(0x38,0);
    lcd_write(0x08,0);
    lcd_write(0x01,0);
    lcd_write(0x06,0);
    lcd_write(0x0C,0);
}

void main(void)
{
    unsigned int ticks;
    unsigned int distance_cm;
    EA=0; TRIG=0; ECHO=1;
    uart_init(); delay_ms(200); lcd_init();
    uart_send_text("ULTRASONIC TEST READY\r\n");
    while(1) {
        ticks=ultrasonic_read();
        if(ticks==0) {
            uart_send_text("NO ECHO\r\n"); lcd_write(0xC0,0); lcd_text("NO ECHO         ");
        } else {
            distance_cm=(unsigned int)(((unsigned long)ticks*10000UL+267264UL)/534528UL);
            lcd_distance(distance_cm); uart_send_text("DIST=");
            uart_send_number(distance_cm);
            uart_send_text(" cm, TICKS=");
            uart_send_number(ticks);
            uart_send_text("\r\n");
        }
        delay_ms(200);
    }
}

void keys_poll(void)
{
    unsigned char raw;
    raw = 0;
    if(KEY_PLUS == 0) raw |= 1;
    if(KEY_MINUS == 0) raw |= 2;
    if(raw != key_candidate) {
        key_candidate = raw;
        key_samples = 1;
    } else if(key_samples < 3) {
        key_samples++;
    }
    if(key_samples < 3 || raw == key_stable) return;
    key_stable = raw;
    if(raw == 0) {
        key_armed = 1;
        return;
    }
    if(!key_armed) return;
    key_armed = 0;
    if(raw == 1 && limit_cm < 200) {
        limit_cm += 5;
        lcd_limit();
    } else if(raw == 2 && limit_cm > 5) {
        limit_cm -= 5;
        lcd_limit();
    }
}

void timer2_isr(void) interrupt 5 using 1
{
    TF2 = 0;
    EXF2 = 0;
    quarter_count++;
    if(quarter_count >= 4) {
        quarter_count = 0;
        if(alarm_on) {
            if(phase_ms != 0) phase_ms--;
            if(phase_ms == 0) {
                burst_on = !burst_on;
                phase_ms = burst_on ? 50 : quiet_ms;
            }
        }
    }
    if(alarm_on && burst_on) BEEP = !BEEP;
    else BEEP = 1;
}
